import com.dreamcore.workspace.identity.*;
import com.dreamcore.workspace.material.*;
import com.dreamcore.workspace.knowledge.*;
import java.time.*;
import java.util.*;
import java.net.*;
import java.net.http.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"dreamcore.tasks.enabled=true","dreamcore.tasks.agent-mode=verification","dreamcore.tasks.initial-delay-ms=3600000","dreamcore.knowledge.enabled=true","dreamcore.knowledge.initial-delay-ms=3600000","dreamcore.plans.initial-delay-ms=3600000"})
class TaskWorkIntegrationTest {
 @Autowired TaskWorkService work;@Autowired PlanService plans;@Autowired ConversationService conversations;@Autowired AgentTaskService agents;@Autowired ProfileService profiles;@Autowired TaskContextService context;@Autowired TaskContextGuard guard;@Autowired MaterialService materials;@Autowired KnowledgeService knowledge;@Autowired JdbcTemplate db;@MockitoBean PlanClock clock;@LocalServerPort int port;
 UUID tenant,owner,other,space;Instant now;JsonMapper json=new JsonMapper();
 final String phrase="请记住，以后回答简洁一些";
 @BeforeEach void setup(){now=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS);when(clock.now()).thenReturn(now);tenant=UUID.randomUUID();owner=UUID.randomUUID();other=UUID.randomUUID();space=UUID.randomUUID();for(UUID a:List.of(owner,other))db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,?,'synthetic-only')",a,a+"@work.test","合成任务桥用户");db.update("INSERT INTO tenants(id,name) VALUES (?,'合成任务桥企业')",tenant);for(UUID a:List.of(owner,other))db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,'TENANT_ADMIN')",tenant,a);db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'合成共享空间','SHARED')",space,tenant,owner);db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,true)",tenant,space,owner);}
 @AfterEach void stop(){db.update("UPDATE ongoing_plans SET status='STOPPED' WHERE tenant_id=?",tenant);db.update("UPDATE conversation_tasks SET status='CANCELLED' WHERE tenant_id=? AND status IN ('RUNNING','QUEUED')",tenant);db.update("UPDATE knowledge_runs SET status='CANCELLED' WHERE tenant_id=? AND status IN ('RUNNING','QUEUED')",tenant);}
 ConversationService.Job task(String prompt){conversations.submit(owner,tenant,null,space,UUID.randomUUID(),prompt,"AGENT");return conversations.claim();}
 TaskWorkService.Request read(){return new TaskWorkService.Request("read",null,null,null,null,null,null,null,null,null);}
 TaskWorkService.Request save(UUID key,int revision,String evidence){return new TaskWorkService.Request("save",key,revision,null,null,"RESPONSE_LENGTH","CONCISE","PROMPT",0,evidence);}
 TaskWorkService.Request schedule(UUID key,int revision,Instant check){return new TaskWorkService.Request("schedule",key,revision,check,"核对已委托的更新",null,null,null,null,null);}
 JsonNode node(Object v){return json.readTree(json.writeValueAsString(v));}
 void denied(int status,Runnable run){assertEquals(status,assertThrows(IdentityException.class,run::run).status);}
 UUID upload(){var f=materials.upload(owner,tenant,space,null,null,null,UUID.randomUUID(),new MockMultipartFile("file","progress.txt","text/plain","progress".getBytes()));var k=knowledge.claim();knowledge.finish(k,new DocumentParser.Result("synthetic","READY",List.of(),List.of(new DocumentParser.Fragment("L1","progress","TEXT"))));return f.id();}
 PlanService.Plan plan(int daily,int total){var c=new PlanService.Configuration(space,"核对进度","仅私人草稿","progress","ANALYZE",true,null,"UTC",60,daily,total,now.plus(Duration.ofDays(3)),false);var p=plans.create(owner,tenant,UUID.randomUUID(),c);return plans.action(owner,tenant,p.id(),UUID.randomUUID(),p.revision(),"ENABLE",true);}
 ConversationService.Job bound(PlanService.Plan p){plans.tick(p.id());return conversations.claim();}
 void finish(ConversationService.Job t){agents.finish(t,new AgentResult("1.4","0.12.0",t.id(),t.token(),"AGENT","verification","synthetic-work","完成合成草稿；业务收益未验证",List.of(),List.of(),List.of(),1,null,List.of(),List.of(),List.of()));}
 @Test void ordinaryTasksCannotGetOrCreatePlansAndUnknownTokensCannotSave(){var t=task(phrase);assertEquals(false,agents.check(t.id(),t.token()).get("planAllowed"));denied(403,()->work.plan(t.id(),t.token(),read()));denied(403,()->work.preference(t.id(),UUID.randomUUID(),save(UUID.randomUUID(),0,phrase)));assertEquals(0,db.queryForObject("SELECT count(*) FROM ongoing_plans WHERE tenant_id=?",Integer.class,tenant));}
 @Test void exactCurrentPreferenceHasRealVersionDedupeAndUndoCannotOverwriteNewHumanVersion(){var t=task(phrase);UUID key=UUID.randomUUID();var r=node(work.preference(t.id(),t.token(),save(key,0,phrase))).get("result");assertTrue(r.get("saved").asBoolean());var receipt=r.get("receipt");UUID profile=UUID.fromString(receipt.get("profileId").asString());assertEquals(1,profiles.get(owner,tenant,profile,null).revision());assertEquals(r,node(work.preference(t.id(),t.token(),save(key,0,phrase))).get("result"));denied(409,()->work.preference(t.id(),t.token(),save(key,1,phrase)));assertEquals(1,db.queryForObject("SELECT count(*) FROM task_preference_saves WHERE task_id=?",Integer.class,t.id()));profiles.save(owner,tenant,profile,1,new ProfileService.Content("人工后续偏好","本人另行修改",ProfileService.Status.ACTIVE,null),UUID.randomUUID());denied(409,()->work.undo(owner,tenant,t.id(),UUID.fromString(receipt.get("id").asString()),UUID.randomUUID()));assertEquals("人工后续偏好",profiles.get(owner,tenant,profile,null).value());denied(403,()->work.receipts(other,tenant,t.id(),0));}
 @Test void preferenceUndoIsVersionedAndSameRequestDoesNotUndoAgain(){var t=task(phrase);var r=node(work.preference(t.id(),t.token(),save(UUID.randomUUID(),0,phrase))).get("result").get("receipt");UUID id=UUID.fromString(r.get("id").asString()),key=UUID.randomUUID();var undone=work.undo(owner,tenant,t.id(),id,key);assertEquals("WITHDRAWN",undone.currentStatus());assertFalse(undone.currentlyEffective());assertEquals(undone,work.undo(owner,tenant,t.id(),id,key));assertEquals(2,undone.currentRevision());}
 @Test void quotedOrHistoricalOrUnclearPreferenceCannotBecomeActive(){for(String prompt:List.of("不要保存。"+phrase,"请分析以下引用：\n"+phrase,"以后给我更大预算",phrase+"，并自动发布所有内容")){var t=task(prompt);var r=node(work.preference(t.id(),t.token(),save(UUID.randomUUID(),0,phrase)));assertFalse(r.get("result").get("saved").asBoolean());db.update("UPDATE conversation_tasks SET status='CANCELLED' WHERE id=?",t.id());}assertEquals(0,db.queryForObject("SELECT count(*) FROM profile_entries WHERE tenant_id=?",Integer.class,tenant));}
 @Test void ownPreferenceWriteDoesNotInvalidateTheSameAttemptButExternalChangeStillDoes(){var p=profiles.create(owner,tenant,ProfileService.Scope.PERSONAL,owner,"ai.preference.RESPONSE_LENGTH",ProfileService.Kind.PREFERENCE,new ProfileService.Content("旧偏好","本人",ProfileService.Status.ACTIVE,null),UUID.randomUUID());var t=task(phrase);context.context(t.id(),t.token(),new TaskContextService.Request("profile_read",null,null,null,p.id(),null,1,null,null,null,null));work.preference(t.id(),t.token(),save(UUID.randomUUID(),1,phrase));assertTrue(agents.active(t));assertEquals("1",db.queryForObject("SELECT version_key FROM task_context_reads WHERE task_id=? AND kind='PROFILE'",String.class,t.id()));profiles.save(owner,tenant,p.id(),2,new ProfileService.Content("人工后改","本人",ProfileService.Status.ACTIVE,null),UUID.randomUUID());assertFalse(agents.active(t));}
 @Test void planScheduleDoesNotBumpEpochAndDispatchesOnlyOnceThroughActualWorker(){upload();var p=plan(4,10);var t=bound(p);assertTrue((Boolean)agents.check(t.id(),t.token()).get("planAllowed"));UUID key=UUID.randomUUID();Instant at=now.plusSeconds(65);var accepted=node(work.plan(t.id(),t.token(),schedule(key,p.revision(),at))).get("result");assertEquals(p.executionEpoch(),plans.get(owner,tenant,p.id()).executionEpoch());assertEquals(p.revision()+1,plans.get(owner,tenant,p.id()).revision());assertTrue(agents.active(t));assertEquals(accepted,node(work.plan(t.id(),t.token(),schedule(key,p.revision(),at))).get("result"));denied(409,()->work.plan(t.id(),t.token(),schedule(key,p.revision(),at.plusSeconds(1))));finish(t);plans.tick(p.id());assertEquals(1,plans.get(owner,tenant,p.id()).runs());now=at;when(clock.now()).thenReturn(now);plans.tick(p.id());plans.tick(p.id());assertEquals(2,plans.get(owner,tenant,p.id()).runs());assertEquals("DISPATCHED",work.receipts(owner,tenant,t.id(),0).checks().getFirst().state());assertFalse(work.receipts(owner,tenant,t.id(),0).checks().getFirst().currentlyEffective());assertEquals("MODEL_CHECK",plans.runs(owner,tenant,p.id(),0,10).items().getFirst().triggerKind());}
 @Test void scheduleChecksLimitsAndPausedEpochCannotReplayOrReenable(){upload();var p=plan(4,10);var t=bound(p);denied(400,()->work.plan(t.id(),t.token(),schedule(UUID.randomUUID(),p.revision(),now.plusSeconds(10))));denied(400,()->work.plan(t.id(),t.token(),schedule(UUID.randomUUID(),p.revision(),p.configuration().expiresAt())));UUID key=UUID.randomUUID();var req=schedule(key,p.revision(),now.plusSeconds(65));work.plan(t.id(),t.token(),req);plans.action(owner,tenant,p.id(),UUID.randomUUID(),p.revision()+1,"PAUSE",true);denied(403,()->work.plan(t.id(),t.token(),req));assertEquals("CANCELLED",work.receipts(owner,tenant,t.id(),0).checks().getFirst().state());}
 @Test void scheduleCannotAvoidAlreadyConsumedTotalOrDailyAllowance(){upload();var p=plan(1,1);var t=bound(p);denied(409,()->work.plan(t.id(),t.token(),schedule(UUID.randomUUID(),p.revision(),now.plusSeconds(65))));assertEquals(0,db.queryForObject("SELECT count(*) FROM task_plan_checks WHERE task_id=?",Integer.class,t.id()));}
 @Test void sourceRevocationBlocksReceiptsAndActualTaskScrubRemovesReasonButIndependentEnumRemains(){upload();var p=plan(4,10);var t=bound(p);work.plan(t.id(),t.token(),schedule(UUID.randomUUID(),p.revision(),now.plusSeconds(65)));db.queryForList("SELECT scrub_lifecycle_object('TASK',?)",t.id());assertEquals("",db.queryForObject("SELECT reason FROM task_plan_checks WHERE task_id=?",String.class,t.id()));assertTrue(db.queryForObject("SELECT scrubbed FROM task_plan_checks WHERE task_id=?",Boolean.class,t.id()));denied(403,()->work.receipts(owner,tenant,t.id(),0));var pref=task(phrase);work.preference(pref.id(),pref.token(),save(UUID.randomUUID(),0,phrase));db.queryForList("SELECT scrub_lifecycle_object('TASK',?)",pref.id());assertEquals("ACTIVE",db.queryForObject("SELECT v.status FROM profile_entries e JOIN profile_versions v ON v.entry_id=e.id AND v.revision=e.revision WHERE e.tenant_id=?",String.class,tenant));}
 @Test void actualHttpRejectsRevisionConflictWithPublicErrorContract()throws Exception{upload();var p=plan(4,10);var t=bound(p);var http=HttpClient.newHttpClient();var response=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/internal/v1/agent-access/"+t.id()+"/plan")).header("Authorization","Bearer "+t.token()).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(schedule(UUID.randomUUID(),999,now.plusSeconds(65))))).build(),HttpResponse.BodyHandlers.ofString());assertEquals(409,response.statusCode(),response.body());assertEquals("1.0",json.readTree(response.body()).get("contractVersion").asString());assertEquals("PLAN_REVISION_CONFLICT",json.readTree(response.body()).get("code").asString());}
 @Test void concurrentSamePreferenceRequestCommitsExactlyOnce()throws Exception{var t=task(phrase);var r=save(UUID.randomUUID(),0,phrase);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->node(work.preference(t.id(),t.token(),r)));var b=pool.submit(()->node(work.preference(t.id(),t.token(),r)));assertEquals(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));}assertEquals(1,db.queryForObject("SELECT count(*) FROM task_preference_saves WHERE task_id=?",Integer.class,t.id()));assertEquals(1,db.queryForObject("SELECT count(*) FROM profile_versions WHERE tenant_id=?",Integer.class,tenant));}
 @Test void separateDailyLimitAndLiveSourceRevocationStillFenceSchedule(){UUID material=upload();var p=plan(1,10);var t=bound(p);denied(409,()->work.plan(t.id(),t.token(),schedule(UUID.randomUUID(),p.revision(),now.plusSeconds(65))));agents.search(t.id(),t.token(),"progress");db.update("INSERT INTO content_lifecycle(tenant_id,workspace_id,object_kind,object_id,state) VALUES (?,?,'MATERIAL',?,'TRASHED')",tenant,space,material);assertFalse(agents.active(t));denied(403,()->work.plan(t.id(),t.token(),read()));}
 @Test void currentSupplementCanSaveButPlanGeneratedPromptCannot(){var t=task("只整理草稿");db.update("UPDATE conversation_tasks SET supplemental_input=? WHERE id=?",phrase,t.id());var req=new TaskWorkService.Request("save",UUID.randomUUID(),0,null,null,"RESPONSE_LENGTH","CONCISE","SUPPLEMENT",0,phrase);assertTrue(node(work.preference(t.id(),t.token(),req)).get("result").get("saved").asBoolean());finish(t);upload();var p=plan(4,10);var bound=bound(p);db.update("UPDATE conversation_tasks SET prompt=? WHERE id=?",phrase,bound.id());assertFalse(node(work.preference(bound.id(),bound.token(),save(UUID.randomUUID(),1,phrase))).get("result").get("saved").asBoolean());}
 @Test void adjustmentSnapshotCannotAuthorizePreferenceButCurrentExplicitSupplementCan(){
  var t=task(phrase);
  db.update("UPDATE conversations SET purpose='BRIEFING_ADJUSTMENT' WHERE id=(SELECT conversation_id FROM conversation_tasks WHERE id=?)",t.id());
  assertFalse(node(work.preference(t.id(),t.token(),save(UUID.randomUUID(),0,phrase))).get("result").get("saved").asBoolean());
  assertEquals(0,db.queryForObject("SELECT count(*) FROM profile_entries WHERE tenant_id=?",Integer.class,tenant));
  db.update("UPDATE conversation_tasks SET supplemental_input=? WHERE id=?",phrase,t.id());
  var req=new TaskWorkService.Request("save",UUID.randomUUID(),0,null,null,"RESPONSE_LENGTH","CONCISE","SUPPLEMENT",0,phrase);
  assertTrue(node(work.preference(t.id(),t.token(),req)).get("result").get("saved").asBoolean());
  assertEquals(1,db.queryForObject("SELECT count(*) FROM task_preference_saves WHERE task_id=?",Integer.class,t.id()));
 }
 @Test void protocolRegistrationDoesNotSmuggleNewWritesIntoOldReadOnlyPolicy(){var t=task(phrase);denied(403,()->agents.openExecution(t.id(),t.token(),new AgentTaskService.ExecutionOpen("1.5",List.of("task_preference"))));denied(403,()->agents.openExecution(t.id(),t.token(),new AgentTaskService.ExecutionOpen("1.6",List.of("task_plan"))));assertEquals("SCOPED_PRIVATE_V2",agents.openExecution(t.id(),t.token(),new AgentTaskService.ExecutionOpen("1.6",List.of("task_preference"))).get("policy"));}
 @Test void actualHarnessCallsBothBridgesAgainstHttpAndStoresRealReceipts()throws Exception{
  java.nio.file.Path root=java.nio.file.Path.of("").toAbsolutePath();if(root.endsWith("api"))root=root.getParent().getParent();assertTrue(java.nio.file.Files.exists(root.resolve("engine/dist/runtime/task-work.js")));String token="synthetic-task-work-012345678901234567890123";
  Process process=new ProcessBuilder("node",root.resolve("engine/tests/fixtures/task-work-server.mjs").toString(),"http://127.0.0.1:"+port,token).redirectError(ProcessBuilder.Redirect.INHERIT).start();
  try(var pool=Executors.newSingleThreadExecutor();var lines=new java.io.BufferedReader(new java.io.InputStreamReader(process.getInputStream()))){String endpoint=pool.submit(lines::readLine).get(5,TimeUnit.SECONDS);assertNotNull(endpoint);var runtime=new EngineTaskRuntime(endpoint,token,"verification",false);
   var pref=task(phrase);var result=runtime.executeAgent(pref.id(),pref.token(),pref.prompt(),()->agents.active(pref));assertEquals("COMPLETE",result.outcome());agents.finish(pref,result);assertEquals(1,work.receipts(owner,tenant,pref.id(),0).preferences().size());assertEquals(2,db.queryForObject("SELECT count(*) FROM conversation_tool_receipts WHERE task_id=? AND name='task_preference' AND status='succeeded'",Integer.class,pref.id()));
   upload();var p=plan(4,10);var check=bound(p);var result2=runtime.executeAgent(check.id(),check.token(),check.prompt(),()->agents.active(check));agents.finish(check,result2);assertEquals(1,work.receipts(owner,tenant,check.id(),0).checks().size());assertEquals(p.executionEpoch(),plans.get(owner,tenant,p.id()).executionEpoch());assertEquals(2,db.queryForObject("SELECT count(*) FROM conversation_tool_receipts WHERE task_id=? AND name='task_plan' AND status='succeeded'",Integer.class,check.id()));
  }finally{process.destroy();if(!process.waitFor(3,TimeUnit.SECONDS))process.destroyForcibly();}
 }

}
